import{_ as s,o as n,c as t,ag as e}from"./chunks/framework.CmaAMB6e.js";const g=JSON.parse('{"title":"09 · CDN 与边缘","description":"","frontmatter":{"概念":"CDN 与边缘","技能":"system-design","阶段":"2-基础组件","状态":"⬜未开始","更新日期":"2026-08-01T00:00:00.000Z"},"headers":[],"relativePath":"system-design/concepts/09-cdn.md","filePath":"system-design/concepts/09-cdn.md","lastUpdated":null}'),p={name:"system-design/concepts/09-cdn.md"};function l(o,a,d,r,i,c){return n(),t("div",null,[...a[0]||(a[0]=[e(`<h1 id="_09-·-cdn-与边缘" tabindex="-1">09 · CDN 与边缘 <a class="header-anchor" href="#_09-·-cdn-与边缘" aria-label="Permalink to &quot;09 · CDN 与边缘&quot;">​</a></h1><h2 id="概念简介" tabindex="-1">概念简介 <a class="header-anchor" href="#概念简介" aria-label="Permalink to &quot;概念简介&quot;">​</a></h2><p>CDN（Content Delivery Network，内容分发网络）把静态内容复制到<strong>离用户最近</strong>的边缘节点，让「北京用户访问北京节点、上海用户访问上海节点」，而不是所有人挤回源站。它的本质是「<strong>把缓存部署到网络边缘</strong>」——地理维度的分布式缓存。用户感知的提升是决定性的：跨省回源 100ms+，命中边缘节点 20ms 以内。</p><p>对前端工程师来说，CDN 是最熟悉的陌生组件：<strong>每次 <code>npm run build</code> 产出的 hash 文件名资源，就是为了配合 CDN 缓存</strong>。前端关心「浏览器缓存怎么失效」，后端要回答「CDN 缓存怎么失效、命中率怎么保证、动态内容怎么办」——前后端对缓存的理解在这里合流。</p><p>本章覆盖：CDN 原理（边缘节点与回源）、缓存策略（TTL 与缓存键）、动态 vs 静态内容、以及与前端构建产物（hash 文件名）的联动。核心心智：<strong>CDN 是「以空间换延迟」</strong>——多副本占存储，但省了带宽、降了延迟，命中率是衡量这一切的关键指标。</p><h2 id="核心内容" tabindex="-1">核心内容 <a class="header-anchor" href="#核心内容" aria-label="Permalink to &quot;核心内容&quot;">​</a></h2><h4 id="_1-cdn-原理-边缘节点与回源" tabindex="-1">1. CDN 原理：边缘节点与回源 <a class="header-anchor" href="#_1-cdn-原理-边缘节点与回源" aria-label="Permalink to &quot;1. CDN 原理：边缘节点与回源&quot;">​</a></h4><div class="language-text vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>无 CDN：所有用户直连源站</span></span>
<span class="line"><span>  上海用户 ──► 源站（北京机房）      延迟高、源站带宽被吃满</span></span>
<span class="line"><span></span></span>
<span class="line"><span>有 CDN：</span></span>
<span class="line"><span>  上海用户 ──► 上海边缘节点 ──► 源站（首次未命中才回源）</span></span>
<span class="line"><span>  北京用户 ──► 北京边缘节点      命中后本地直接返回</span></span>
<span class="line"><span>  广州用户 ──► 广州边缘节点</span></span>
<span class="line"><span>  → 每个边缘节点都缓存一份内容，源站只被「未命中」的请求访问</span></span>
<span class="line"><span></span></span>
<span class="line"><span>请求流转（DNS 调度）：</span></span>
<span class="line"><span>  用户请求 static.example.com</span></span>
<span class="line"><span>    → DNS 根据用户地理位置返回最近的边缘节点 IP</span></span>
<span class="line"><span>    → 边缘节点查缓存：命中返回；未命中回源站拉取并缓存</span></span></code></pre></div><p>关键点：<strong>回源是「按需 + 逐级」的</strong>——边缘节点先查自己的缓存，没有才回源；命中率高的资源，源站几乎零流量。CDN 的收益三合一：用户延迟下降、源站带宽成本下降、源站抗压能力上升。</p><h4 id="_2-缓存策略-ttl-与缓存键" tabindex="-1">2. 缓存策略：TTL 与缓存键 <a class="header-anchor" href="#_2-缓存策略-ttl-与缓存键" aria-label="Permalink to &quot;2. 缓存策略：TTL 与缓存键&quot;">​</a></h4><p>CDN 缓存行为由<strong>源站响应头</strong>控制（回源时带回，边缘节点遵守）：</p><div class="language-text vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>源站返回的 HTTP 响应头 → 决定边缘节点如何缓存：</span></span>
<span class="line"><span></span></span>
<span class="line"><span>Cache-Control: public, max-age=31536000, immutable</span></span>
<span class="line"><span>  → 可被 CDN 缓存（public），缓存 1 年，不可变</span></span>
<span class="line"><span>  → 用于 hash 文件名资源（见第 4 节）</span></span>
<span class="line"><span></span></span>
<span class="line"><span>Cache-Control: public, max-age=60</span></span>
<span class="line"><span>  → 缓存 60 秒：适合「允许 1 分钟延迟」的接口数据</span></span>
<span class="line"><span></span></span>
<span class="line"><span>Cache-Control: private / no-store</span></span>
<span class="line"><span>  → 不缓存：用户私有数据（个人详情）绝不进 CDN</span></span>
<span class="line"><span></span></span>
<span class="line"><span>Cache-Control: no-cache</span></span>
<span class="line"><span>  → 缓存但每次回源校验（ETag/Last-Modified 协商）</span></span>
<span class="line"><span>  → 适合「需要新鲜但可以省流量」的内容</span></span></code></pre></div><p>缓存键（Cache Key）决定「什么算同一个资源」：默认是 URL，但<strong>查询参数不同则缓存键不同</strong>（<code>?v=1</code> 与 <code>?v=2</code> 是两份）。工程坑：把动态参数（时间戳、随机数）放进 URL 会让缓存键爆炸、命中率归零——<strong>动态参数要挪到 Header/Cookie，或明确不进 CDN</strong>。</p><h4 id="_3-动态-vs-静态内容-两条完全不同的路" tabindex="-1">3. 动态 vs 静态内容：两条完全不同的路 <a class="header-anchor" href="#_3-动态-vs-静态内容-两条完全不同的路" aria-label="Permalink to &quot;3. 动态 vs 静态内容：两条完全不同的路&quot;">​</a></h4><table tabindex="0"><thead><tr><th>维度</th><th>静态内容</th><th>动态内容</th></tr></thead><tbody><tr><td>例子</td><td>构建产物、图片、视频</td><td>用户信息、实时库存、个性化推荐</td></tr><tr><td>能否缓存</td><td>能，且应该尽量缓存</td><td>基本不能（因人而异、实时变化）</td></tr><tr><td>TTL 策略</td><td>长缓存（1 年）+ 文件名 hash</td><td>no-store，或极短 TTL + 私有缓存</td></tr><tr><td>CDN 角色</td><td>边缘缓存</td><td>不做 CDN，走应用层（见下面）</td></tr></tbody></table><div class="language-text vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>动态内容的两条出路：</span></span>
<span class="line"><span>  ① 动态接口不加 CDN：走 负载均衡 → 应用 → 数据库（默认路径）</span></span>
<span class="line"><span>  ② 动态资源边缘化：CDN 边缘节点跑计算（边缘函数/边缘渲染）</span></span>
<span class="line"><span>     → 在离用户最近的节点算 HTML，回源只查数据</span></span>
<span class="line"><span>     → 适合「页面骨架动态、数据动态」的 SSR 场景（贵，量级大了再考虑）</span></span></code></pre></div><p>权衡原则：<strong>静态内容无脑进 CDN；动态内容默认不碰 CDN</strong>，等命中率与成本数据出来再评估边缘计算。把「个性化接口」硬塞 CDN 缓存，等于用缓存一致性换一个假的性能提升。</p><h4 id="_4-与前端构建产物联动-hash-文件名的意义" tabindex="-1">4. 与前端构建产物联动：hash 文件名的意义 <a class="header-anchor" href="#_4-与前端构建产物联动-hash-文件名的意义" aria-label="Permalink to &quot;4. 与前端构建产物联动：hash 文件名的意义&quot;">​</a></h4><p>这是前端工程师最容易「顿悟」的一节——<strong>hash 文件名 + 长 TTL 是 CDN 缓存的最佳实践</strong>：</p><div class="language-text vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>构建产物命名（Vite/Webpack 的 contenthash）：</span></span>
<span class="line"><span>  app-8f3d2a.js   vendor-4b1c9e.css   logo-7e1a2c.png</span></span>
<span class="line"><span>    ↑ 内容变化 → hash 变化 → 全新 URL → 浏览器/CDN 视为新资源</span></span>
<span class="line"><span></span></span>
<span class="line"><span>配合 CDN 的缓存配置：</span></span>
<span class="line"><span>  index.html        → Cache-Control: no-cache（每次回源校验，保证拿到最新入口）</span></span>
<span class="line"><span>  *.js / *.css      → Cache-Control: public, max-age=31536000, immutable</span></span>
<span class="line"><span>                      内容变了 hash 变 → 新 URL 新缓存，旧资源自然过期</span></span>
<span class="line"><span>                      内容没变 hash 不变 → 命中缓存，零回源</span></span>
<span class="line"><span></span></span>
<span class="line"><span>发布流程：</span></span>
<span class="line"><span>  构建出带新 hash 的文件 → 上传 CDN/对象存储 → 更新 index.html 引用</span></span>
<span class="line"><span>  → 用户访问 index.html（校验新）→ 加载新 hash 的资源（回源一次，此后全网缓存）</span></span></code></pre></div><p>这个设计把「缓存失效」从「按时间猜」变成「按内容确定」：<strong>资源不可变 → 可以永久缓存；入口文件可变 → 每次校验</strong>。前端构建产物是这个策略的完美执行者——任何系统（后端静态资源、App 包分发）都应该抄这个模式。</p><h4 id="_5-权衡-命中率、刷新与一致性" tabindex="-1">5. 权衡：命中率、刷新与一致性 <a class="header-anchor" href="#_5-权衡-命中率、刷新与一致性" aria-label="Permalink to &quot;5. 权衡：命中率、刷新与一致性&quot;">​</a></h4><p>CDN 引入了「<strong>同一份资源在多个节点有多个副本</strong>」的一致性问题：</p><table tabindex="0"><thead><tr><th>问题</th><th>场景</th><th>解法</th></tr></thead><tbody><tr><td>命中率低</td><td>资源更新太频繁、URL 带动态参数</td><td>hash 文件名 / 稳定 URL + 足够 TTL</td></tr><tr><td>强制刷新</td><td>出了事故要立刻下掉旧资源</td><td>CDN 管理台 purge（全网清除）</td></tr><tr><td>回源压力</td><td>突发流量首次访问全未命中</td><td>预热（发布前主动回源填充）</td></tr><tr><td>脏数据</td><td>接口缓存了不应缓存的数据</td><td>严格区分 public/private 与 TTL</td></tr></tbody></table><p>关键权衡：<strong>长 TTL（性能好、失效慢）vs 短 TTL（失效快、性能差）</strong>——hash 文件名让你可以放心选长 TTL，这是它优于「固定文件名 + 短 TTL」的根本原因。同样，<strong>purge 是最后手段不是日常手段</strong>：天天 purge 说明缓存策略设计错了。</p><h2 id="常见陷阱" tabindex="-1">常见陷阱 <a class="header-anchor" href="#常见陷阱" aria-label="Permalink to &quot;常见陷阱&quot;">​</a></h2><ul><li><strong>固定文件名 + 短 TTL</strong>：<code>app.js</code> 每次发版改 TTL 或靠 purge，命中率低且一致性差；hash 文件名 + 长 TTL 才是正解。</li><li><strong>URL 带动态参数</strong>：<code>?t=时间戳</code> 让缓存键爆炸，命中率归零，CDN 形同虚设；动态参数走 Header/Cookie。</li><li><strong>把私有数据设为 public</strong>：个人资料、订单详情被 CDN 缓存，用户 A 看到用户 B 的数据——安全事故；<code>private</code>/<code>no-store</code> 必须用对。</li><li><strong>index.html 也长缓存</strong>：入口文件被缓存一年，发版后用户永远访问旧页面；入口必须 <code>no-cache</code>。</li><li><strong>所有接口都想过 CDN</strong>：实时性数据（库存/余额）被缓存后卖出超卖；动态内容默认不走 CDN。</li><li><strong>忽略回源链路本身</strong>：回源请求还走公网，边缘节点到源站延迟高，命中率再高也无感；回源应走内网/专线。</li></ul><h2 id="练习建议" tabindex="-1">练习建议 <a class="header-anchor" href="#练习建议" aria-label="Permalink to &quot;练习建议&quot;">​</a></h2><ol><li><strong>基础</strong>：用 Vite/Webpack 构建一个项目，检查产物文件名 hash 变化规则（改一行代码 hash 是否变），配置 <code>Cache-Control</code> 响应头验证浏览器/CDN 的缓存行为（用 DevTools 看 <code>from disk cache</code> 与网络状态）。</li><li><strong>进阶</strong>：部署一个 Nginx 静态服务模拟源站，本地搭 CDN 测试环境（或用云厂商 CDN 控制台），验证：hash 文件名 + <code>max-age=31536000</code> 下「发版更新」的完整缓存行为（哪些请求回源、哪些命中）。</li><li><strong>综合</strong>：设计一个「前后端一体」的静态资源发布方案：构建 → 上传 CDN → 更新 index.html → 预热 → 灰度/回滚，画出发布时序图，说明事故场景下如何用 purge + 回滚旧版本快速恢复。</li></ol><blockquote><p>用 <code>/practice system-design CDN 与边缘</code> 生成更多针对性练习。</p></blockquote><h2 id="前端对照" tabindex="-1">前端对照 <a class="header-anchor" href="#前端对照" aria-label="Permalink to &quot;前端对照&quot;">​</a></h2><table tabindex="0"><thead><tr><th>前端架构概念</th><th>系统设计对应</th></tr></thead><tbody><tr><td>构建产物 contenthash 文件名</td><td>CDN 缓存键：内容变则 URL 变</td></tr><tr><td>浏览器 HTTP 缓存（disk cache）</td><td>CDN 边缘节点缓存（更远一层的同一机制）</td></tr><tr><td>静态资源部署到对象存储</td><td>CDN 源站（回源拉取）</td></tr><tr><td>Service Worker 离线缓存</td><td>边缘缓存（把内容放到离使用者更近的地方）</td></tr><tr><td>前端性能优化（LCP 首屏加速）</td><td>CDN 就近分发（地理维度降延迟）</td></tr><tr><td>发布回滚（切旧版本）</td><td>purge + 回滚旧版本（一致性兜底）</td></tr></tbody></table><h2 id="参考链接" tabindex="-1">参考链接 <a class="header-anchor" href="#参考链接" aria-label="Permalink to &quot;参考链接&quot;">​</a></h2><ul><li><a href="https://developer.mozilla.org/zh-CN/docs/Web/HTTP/Caching" target="_blank" rel="noreferrer">MDN：HTTP 缓存（Cache-Control 详解）</a></li><li><a href="https://www.cloudflare.com/learning/cdn/what-is-a-cdn/" target="_blank" rel="noreferrer">Cloudflare CDN 工作原理</a></li><li><a href="https://web.dev/articles/http-cache" target="_blank" rel="noreferrer">web.dev：缓存最佳实践（含 hash 文件名策略）</a></li></ul>`,34)])])}const C=s(p,[["render",l]]);export{g as __pageData,C as default};
